// STL 7 -- Weekly Owner Report. The one page the owner actually reads.
//
// GHL cannot aggregate across contacts, appointments and a custom field in one
// view, which is why this lives in n8n (CLO-11 requirement 4).
//
// Input contract -- one row per lead touched this week:
//   { id, source, received_at, response_seconds|null, automated,
//     booked, showed, no_show_count, recovered, reactivated }
// response_seconds is null when no automated channel fired (Messenger-only
// leads). Those leads are counted as leads but never as sub-60s responses.
// Two shapes reach this node: one item per lead (a GHL fetch loop), or a
// single webhook POST carrying { rows: [...] }. Accept both -- the on-demand
// report and the Monday schedule must produce identical numbers.
const raw = $input.all();
const first = raw.length === 1 ? raw[0].json : null;
const packed = first ? (first.body && first.body.rows) || first.rows : null;
const rows = Array.isArray(packed)
  ? packed
  : raw.map((i) => i.json.lead ?? i.json).filter(Boolean);

const clean = [];
const rejected = [];
for (const r of rows) {
  if (!r.id || !r.received_at) { rejected.push({ row: r, why: 'missing id or received_at' }); continue; }
  const rs = r.response_seconds;
  if (rs != null && (typeof rs !== 'number' || rs < 0)) {
    rejected.push({ row: r, why: 'bad response_seconds' });
    continue;
  }
  clean.push(r);
}

// A silently dropped row understates the numbers the owner is judging us on.
// Surface them on the report rather than hiding them.
// Identity of the report. Both fields must survive the webhook path, not just
// the local harness: they used to be read from $env alone, which rendered the
// live report as "Your clinic -- week of this week" and meant one n8n instance
// could only ever report for one clinic. Per-request payload wins, so client #2
// is a different POST body rather than a host .env edit and a restart.
//
// week_of is DERIVED from the rows when the caller does not name it -- the
// Monday on or before the earliest lead. A static env var goes stale the week
// after it is set; the data cannot.
function mondayOnOrBefore(rows) {
  let earliest = null;
  for (const r of rows) {
    const t = Date.parse(r.received_at);
    if (Number.isFinite(t) && (earliest === null || t < earliest)) earliest = t;
  }
  if (earliest === null) return null;
  const d = new Date(earliest);
  const dow = d.getUTCDay();               // 0 = Sunday
  const back = dow === 0 ? 6 : dow - 1;    // walk back to Monday
  d.setUTCDate(d.getUTCDate() - back);
  return d.toISOString().slice(0, 10);
}

const cfg = (first && first.body) || first || {};

return [{
  json: {
    rows: clean,
    rejected,
    clinic: cfg.clinic || $env.STL_CLINIC_NAME || null,
    week_of: cfg.week_of || mondayOnOrBefore(clean) || $env.STL_REPORT_WEEK_OF || null,
  },
}];

// Every number on the report is computed here, once. No metric is invented in
// the render step.
const BUDGET_S = 60;

function median(nums) {
  if (nums.length === 0) return null;
  const s = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : Math.round(((s[mid - 1] + s[mid]) / 2) * 10) / 10;
}

const item = $input.all()[0].json;
const rows = item.rows;

const answered = rows.filter((r) => r.response_seconds != null);
const inside = answered.filter((r) => r.response_seconds < BUDGET_S);
const booked = rows.filter((r) => r.booked);
const showed = rows.filter((r) => r.showed);
const recovered = rows.filter((r) => r.recovered);
const reactivated = rows.filter((r) => r.reactivated);
const manualOnly = rows.filter((r) => r.response_seconds == null);

// The slowest response is the number that keeps us honest. If it is missing
// from the report, the report is marketing, not reporting.
let slowest = null;
for (const r of answered) {
  if (!slowest || r.response_seconds > slowest.response_seconds) slowest = r;
}

const pct = (n, d) => (d === 0 ? 0 : Math.round((n / d) * 100));

return [{
  json: {
    ...item,
    metrics: {
      new_leads: rows.length,
      answered_count: answered.length,
      inside_budget: inside.length,
      inside_budget_pct: pct(inside.length, answered.length),
      median_response_seconds: median(answered.map((r) => r.response_seconds)),
      booked: booked.length,
      booked_pct: pct(booked.length, rows.length),
      showed: showed.length,
      recovered: recovered.length,
      reactivated: reactivated.length,
      manual_only: manualOnly.length,
      slowest: slowest
        ? { seconds: slowest.response_seconds, at: slowest.received_at, source: slowest.source }
        : null,
      rejected_rows: item.rejected.length,
    },
  },
}];

// Plain text on purpose. It has to survive an SMS preview, a WhatsApp forward
// and a clinic owner reading it on a phone between patients.
const item = $input.all()[0].json;
const m = item.metrics;
// Resolved upstream in Load Week (payload -> env). Falling back here too so a
// direct call into this node still renders something sane.
const clinic = item.clinic || $env.STL_CLINIC_NAME || 'Your clinic';
const weekOf = item.week_of || 'this week';

const pad = (n) => String(n).padStart(4);
const lines = [];
lines.push(clinic + ' -- week of ' + weekOf);
lines.push('');
lines.push('  New leads               ' + pad(m.new_leads));
lines.push('  Answered inside 60s     ' + pad(m.inside_budget) + '  (' + m.inside_budget_pct + '% of automated)');
lines.push('  Median response time    ' + pad(m.median_response_seconds == null ? '--' : m.median_response_seconds) + ' seconds');
lines.push('  Consultations booked    ' + pad(m.booked) + '  (' + m.booked_pct + '% of leads)');
lines.push('  Showed up               ' + pad(m.showed));
lines.push('  No-shows recovered      ' + pad(m.recovered));
lines.push('  Reactivated             ' + pad(m.reactivated));

if (m.manual_only > 0) {
  lines.push('');
  lines.push('  ' + m.manual_only + ' Messenger lead(s) were drafted for a human to send.');
  lines.push('  Those are not counted in the 60-second figure.');
}

if (m.slowest) {
  lines.push('');
  lines.push('  Slowest response this week: ' + m.slowest.seconds + ' seconds (' + m.slowest.at + ', ' + m.slowest.source + ')');
}

if (m.rejected_rows > 0) {
  lines.push('');
  lines.push('  NOTE: ' + m.rejected_rows + ' row(s) were unreadable and are excluded. Check the pipeline.');
}

return [{ json: { ...item, report_text: lines.join('\n') } }];

// Same hard boundary as the intake workflow: no real recipient until a live
// account is signed off. The report goes to the sandbox sink and is returned
// on the response so the demo can show it on screen.
const mode = $env.STL_DELIVERY_MODE || 'sandbox';
const to = $env.STL_OWNER_REPORT_EMAIL || null;

if (mode !== 'sandbox') {
  throw new Error('STL_DELIVERY_MODE=' + mode + ' but no live transport is wired.');
}

const item = $input.all()[0].json;
return [{
  json: {
    ok: true,
    metrics: item.metrics,
    report_text: item.report_text,
    delivery: {
      mode,
      channel: 'email',
      to,
      transport: 'sandbox-sink',
      status: 'delivered',
      subject: 'Your weekly clinic report',
    },
  },
}];
